        const type=pinned.has(b.key)?'pinned-log':manual.has(b.key)?'manual-log':'all-log';
        out.push(makeLogRecallItem(b,slot,type,'날짜로그',type==='all-log'?'전체 포함 후보':'사용자 선택',{score:scores.get(b.key)||0}));
