        if(live.actors.some(a=>a.name===name&&a.id!==resultId))throw new Error('같은 이름의 인물이 있습니다.');
        if(!resultId&&live.actors.length>=30)throw new Error('한 방에서 관리할 인물은 최대 30명입니다.');
        const old=r.actors.find(a=>a.id===resultId);
